if TYPE_CHECKING:
    from collections.abc import Generator, Mapping


def _set_config_attr(config: pytest.Config, name: str, *, value: object) -> None:
    """Set plugin-owned state without extending pytest's typed Config API."""
    setattr(config, name, value)


def nonnegative_int(value: str) -> int:
    """Parse a non-negative integer pytest option."""
    integer = int(value)
    if integer < 0:
        raise ValueError(f"Argument {value} must be non-negative")
    return integer


def pytest_addoption(parser: pytest.Parser) -> None:
    """Add plugin-specific options."""
    group = parser.getgroup(
        "cudf-polars", "Plugin to set GPU as default engine for polars tests"
    )
    group.addoption(
        "--inject-gpu-engine",
        action="store",
        default="in-memory",
        choices=("in-memory", "spmd"),
        help="Which GPU engine variant to inject globally.",
    )
    group.addoption(
        "--inject-gpu-engine-blocksize",
        action="store",
        default="default",
        choices=("default", "small"),
        help=(
            "Blocksize mode for the 'spmd' engine. Set to 'small' to run most "
            "tests with multiple partitions. Ignored for 'in-memory'."
        ),
    )
    group.addoption(
        "--inject-gpu-engine-raise-on-fail",
        action="store_true",
        help=(
            "Force raise_on_fail=True on the injected engine and suppress the "
            "plugin's xfail markers (tests will surface real failures)."
        ),
    )
    group.addoption(
        "--cudf-polars-shard-id",
        dest="cudf_polars_shard_id",
        type=nonnegative_int,
        default=0,
        help="Zero-based index of this cudf-polars test shard.",
    )
    group.addoption(
        "--cudf-polars-num-shards",
        dest="cudf_polars_num_shards",
        type=nonnegative_int,
        default=1,
        help="Total number of cudf-polars test shards.",
    )
    group.addoption(
        "--inject-gpu-engine-require-use",
        action="store_true",
        help="Fail a passing test that does not invoke the injected GPU engine.",
    )


def _sha256_hash(value: str) -> int:
    """Return a stable integer hash for a pytest node ID."""
    return int.from_bytes(hashlib.sha256(value.encode()).digest(), "little")


def partition_items_by_shard(
    items: list[pytest.Item], shard_id: int, num_shards: int
) -> tuple[list[pytest.Item], list[pytest.Item]]:
    """Split items into this shard and items assigned to other shards."""
    selected: list[pytest.Item] = []
    deselected: list[pytest.Item] = []
    for item in items:
        target = (
            selected
            if _sha256_hash(item.nodeid) % num_shards == shard_id
            else deselected
        )
        target.append(item)
    return selected, deselected


def validate_shard_options(shard_id: int, num_shards: int) -> None:
    """Validate cudf-polars test sharding options."""
    if num_shards < 1:
        raise pytest.UsageError(
            f"--cudf-polars-num-shards ({num_shards}) must be at least 1"
        )
    if not 0 <= shard_id < num_shards:
        raise pytest.UsageError(
            "--cudf-polars-shard-id "
            f"({shard_id}) must be in "
            f"[0, --cudf-polars-num-shards ({num_shards}))"
        )


def pytest_report_collectionfinish(
    config: pytest.Config, items: list[pytest.Item]
) -> str | None:
    """Report the number of tests assigned to a non-default shard."""
    num_shards = config.getoption("cudf_polars_num_shards")
    if num_shards > 1:
        shard_id = config.getoption("cudf_polars_shard_id")
        return f"Running {len(items)} items in shard {shard_id}/{num_shards}"
    return None


def pytest_configure(config: pytest.Config) -> None:
    """Enable use of this module as a pytest plugin to enable GPU collection."""
    variant = config.getoption("--inject-gpu-engine")
    blocksize = config.getoption("--inject-gpu-engine-blocksize")
    raise_on_fail = config.getoption("--inject-gpu-engine-raise-on-fail")
    validate_shard_options(
        config.getoption("cudf_polars_shard_id"),
        config.getoption("cudf_polars_num_shards"),
    )
    if variant == "in-memory":
        engine = polars.GPUEngine(executor="in-memory", raise_on_fail=raise_on_fail)
        fallback_engine = polars.GPUEngine(executor="in-memory", raise_on_fail=False)
    else:
        from cudf_polars.engine.spmd import SPMDEngine

        executor_options: dict[str, object] = {}
        if blocksize == "small":
            executor_options["max_rows_per_partition"] = 4
            executor_options["target_partition_size"] = 10
            # We expect many tests to fall back, so silence the warnings.
            executor_options["fallback_mode"] = StreamingFallbackMode.SILENT
        engine = SPMDEngine(
            executor_options=executor_options,
            engine_options={"raise_on_fail": raise_on_fail},
        )
        fallback_engine = SPMDEngine(
            executor_options=executor_options,
            engine_options={"raise_on_fail": False},
        )

    collect = polars.LazyFrame.collect

    def collect_with_injected_engine(
        self: polars.LazyFrame, *args: Any, **kwargs: Any
    ) -> Any:
        nodeid = getattr(config, "_inject_gpu_engine_nodeid", None)
        selected_engine = kwargs.setdefault(
            "engine", fallback_engine if nodeid in _fallbacks_for(config) else engine
        )
        if selected_engine is engine:
            _set_config_attr(config, "_inject_gpu_engine_used", value=True)
        return collect(self, *args, **kwargs)

    polars.LazyFrame.collect = collect_with_injected_engine  # type: ignore[method-assign]
    _set_config_attr(config, "_inject_gpu_engine", value=engine)
    _set_config_attr(config, "_inject_gpu_fallback_engine", value=fallback_engine)
    _set_config_attr(config, "_inject_gpu_engine_used", value=False)
    _verify_collect_patch(engine, collect_with_injected_engine)

    config.addinivalue_line(
        "filterwarnings",
        "ignore:.*GPU engine does not support streaming or background collection",
    )
    config.addinivalue_line(
        "filterwarnings",
        "ignore:.*Query execution with GPU not possible",
    )


def _verify_collect_patch(engine: object, wrapper: object) -> None:
    """Raise if ``polars.LazyFrame.collect`` is not the wrapper we installed."""
    raw = polars.LazyFrame.__dict__.get("collect")
    if raw is not wrapper:
        raise TypeError(
            f"polars.LazyFrame.collect patch failed: expected wrapper, "
            f"got {type(raw).__name__}"
        )


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_setup(item: pytest.Item) -> Generator[None, None, None]:
    """Select the engine before fixtures can execute lazy queries."""
    config = item.config
    _set_config_attr(config, "_inject_gpu_engine_nodeid", value=item.nodeid)
    _set_config_attr(config, "_inject_gpu_engine_used", value=False)
    fallback_used.set(False)
    yield


@pytest.hookimpl(hookwrapper=True)
def pytest_runtest_call(item: pytest.Item) -> Generator[None, None, None]:
    """Validate that an explicit fallback exception really fell back."""
    outcome = yield
    config = item.config
    if (
        getattr(outcome, "excinfo", None) is None
        and item.nodeid in _fallbacks_for(config)
        and not fallback_used.get()
    ):
        pytest.fail("CPU-fallback exception did not fall back; remove it from the list")
    _set_config_attr(config, "_inject_gpu_engine_nodeid", value=None)


def pytest_unconfigure(config: pytest.Config) -> None:
    """Tear down the injected engine."""
    engine = getattr(config, "_inject_gpu_engine", None)
    if engine is None:
        return
    shutdown = getattr(engine, "shutdown", None)
    if shutdown is not None:
        shutdown()


def pytest_report_header(config: pytest.Config) -> str:
    """Report which GPU engine has been injected into polars.LazyFrame.collect."""
    engine = getattr(config, "_inject_gpu_engine", None)
    cls = type(engine)
    return f"injected GPU engine: {cls.__module__}.{cls.__name__}"


